// Speed-to-Lead v1 -- normalize every inbound source into one lead shape.
// Sources: mockup form (web), Facebook message, missed call.
const t0 = Date.now();
const out = [];

for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  const q = item.json.query ?? {};
  const raw = { ...q, ...b };

  const source = String(raw.source ?? 'web_form').toLowerCase().trim();
  const digits = String(raw.phone ?? raw.from ?? '').replace(/[^0-9+]/g, '');
  const email = String(raw.email ?? '').trim().toLowerCase();
  const name = String(raw.name ?? raw.full_name ?? '').trim();
  // Messenger hands us a page-scoped id, never a phone number. It is a real
  // reachable channel -- but only a human may send on it (see Deliver First
  // Touch). Treat it as reachable so we stop rejecting the commonest FB lead.
  const psid = String(raw.psid ?? raw.sender_id ?? raw.thread_id ?? '').trim();
  const pageId = String(raw.page_id ?? raw.page ?? '').trim();

  const problems = [];
  if (!['web_form', 'facebook', 'missed_call'].includes(source)) {
    problems.push('unknown_source:' + source);
  }
  if (psid && source !== 'facebook') problems.push('psid_on_non_facebook_source');
  if (!digits && !email && !(source === 'facebook' && psid)) {
    problems.push('no_reachable_channel');
  }
  if (digits && !/^\+?[0-9]{7,15}$/.test(digits)) problems.push('bad_phone');
  if (email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email)) problems.push('bad_email');

  out.push({
    json: {
      t0,
      valid: problems.length === 0,
      problems,
      lead: {
        source,
        name: name || 'there',
        phone: digits || null,
        email: email || null,
        psid: psid || null,
        page_id: pageId || null,
        message: String(raw.message ?? raw.text ?? '').trim(),
        clinic: String(raw.clinic ?? raw.business ?? 'the clinic').trim(),
        mockup_url: raw.mockup_url ?? null,
        received_at: new Date(t0).toISOString(),
      },
    },
  });
}

return out;

// Clinic-flavoured first-touch copy. Kept in one place so the GHL snapshot and
// the n8n workflow never drift apart.
const BOOKING_URL = $env.STL_BOOKING_URL || 'https://api.leadconnectorhq.com/widget/booking/QRPEnWRw2Kx9rBe0Mj6J';

return $input.all().map((item) => {
  const l = item.json.lead;
  const first = l.name.split(' ')[0];

  const sms =
    'Hi ' + first + ', this is ' + l.clinic + '. Thanks for reaching out! ' +
    'Are you looking to book a consultation? Reply with a day that suits you ' +
    'and I will get you in. Or book directly: ' + BOOKING_URL;

  const emailSubject = 'Re: your enquiry to ' + l.clinic;
  const emailBody =
    'Hi ' + first + ',\n\n' +
    'Thanks for getting in touch with ' + l.clinic + '.\n\n' +
    (l.message ? 'You wrote: "' + l.message + '"\n\n' : '') +
    'We have consultation slots open this week. Pick a time here: ' + BOOKING_URL + '\n\n' +
    'If you would rather talk first, just reply to this email.\n\n' +
    '-- ' + l.clinic;

  // Messenger copy is shorter and unsigned -- it renders in a chat bubble, not
  // an inbox. Same booking link, so every channel converges on one calendar.
  const messenger =
    'Hi ' + first + '! Thanks for messaging ' + l.clinic + '. ' +
    'Would you like to book a consultation? Grab a slot here: ' + BOOKING_URL +
    ' -- or tell me a day that works and I will sort it out.';

  return {
    json: {
      ...item.json,
      messages: {
        sms: l.phone ? { to: l.phone, body: sms } : null,
        email: l.email ? { to: l.email, subject: emailSubject, body: emailBody } : null,
        messenger: l.psid ? { to: l.psid, page_id: l.page_id, body: messenger } : null,
      },
    },
  };
});

// SANDBOX TRANSPORT.
// Hard boundary: this workflow must never send a real SMS or email to a real
// person. STL_DELIVERY_MODE must stay 'sandbox' unless a live client account
// has been signed off by the CEO. Swapping to Twilio/SMTP is a transport change
// here only -- nothing upstream or downstream moves.
//
// MESSENGER IS DIFFERENT AND ALWAYS WILL BE. Facebook does not permit automated
// sending on these threads and we do not fake it. The engine drafts the reply
// and queues it for a human with a deadline. Automating up to the send is the
// product; automating the send is a ban.
const mode = $env.STL_DELIVERY_MODE || 'sandbox';
const MANUAL_SLA_MS = 60000;

if (mode !== 'sandbox') {
  throw new Error(
    'STL_DELIVERY_MODE=' + mode + ' but no live transport is wired. ' +
    'Refusing to silently drop messages.'
  );
}

return $input.all().map((item) => {
  const m = item.json.messages;
  const attempts = [];
  const manual_actions = [];

  if (m.sms) {
    attempts.push({ channel: 'sms', to: m.sms.to, transport: 'sandbox-sink', status: 'delivered', chars: m.sms.body.length });
  }
  if (m.email) {
    attempts.push({ channel: 'email', to: m.email.to, transport: 'sandbox-sink', status: 'delivered', subject: m.email.subject });
  }
  if (m.messenger) {
    manual_actions.push({
      channel: 'messenger',
      to: m.messenger.to,
      transport: 'manual-queue',
      status: 'awaiting_human_send',
      due_by: new Date(item.json.t0 + MANUAL_SLA_MS).toISOString(),
      thread_url: m.messenger.page_id
        ? 'https://business.facebook.com/latest/inbox/all?asset_id=' + m.messenger.page_id
        : null,
      draft: m.messenger.body,
    });
  }

  return {
    json: {
      ...item.json,
      delivery: { mode, attempts, manual_actions, delivered_at: new Date().toISOString() },
    },
  };
});

// The GHL agency API is unconfigured (list_locations -> "dependencies are not
// configured"). Rather than stall the demo, park a replay-ready payload. When
// the credential is restored, the true branch takes over and this queue is
// drained -- see automation/n8n/README.md, "When the GHL credential comes back".
const configured = ($env.GHL_SANDBOX_LOCATION_ID || '').trim().length > 0;

return $input.all().map((item) => ({
  json: {
    ...item.json,
    ghl: {
      configured,
      pipeline_id: '7yd9fhvPcfz1vqbF3kxN',
      stage: 'New Lead',
      tags: ['speed-to-lead', 'source-' + item.json.lead.source],
      upsert_payload: {
        firstName: item.json.lead.name,
        phone: item.json.lead.phone,
        email: item.json.lead.email,
        source: item.json.lead.source,
      },
    },
  },
}));

// GHL configured -- placeholder for the HTTP upsert against the sandbox
// location. Left inert until the credential is restored so the workflow imports
// and runs cleanly either way (CLO-14 scope item 2).
return $input.all().map((item) => ({
  json: { ...item.json, crm: { status: 'upsert_pending_wiring', location: $env.GHL_SANDBOX_LOCATION_ID } },
}));

// GHL not configured -- record the contact upsert so nothing is lost.
return $input.all().map((item) => ({
  json: { ...item.json, crm: { status: 'queued_for_replay', reason: 'ghl_credential_unconfigured' } },
}));

// The claim the whole pitch rests on: first touch inside 60 seconds.
// pipeline_ms measures normalize -> respond inside n8n. It excludes inbound
// network latency to the webhook; the end-to-end number is measured from the
// caller's side by automation/n8n/test/speed-to-lead-smoke.mjs.
//
// `automated` is the honest qualifier. A Messenger-only lead is DRAFTED in
// milliseconds but SENT by a human, so it does not get to claim the sub-60s
// number. Outreach quotes the sub-60s line for SMS and email only.
const BUDGET_MS = 60000;

return $input.all().map((item) => {
  const pipeline_ms = Date.now() - item.json.t0;
  const attempts = item.json.delivery.attempts ?? [];
  const manual = item.json.delivery.manual_actions ?? [];
  return {
    json: {
      ok: true,
      lead: item.json.lead,
      delivery: item.json.delivery,
      crm: item.json.crm,
      timing: {
        pipeline_ms,
        budget_ms: BUDGET_MS,
        within_budget: pipeline_ms < BUDGET_MS,
        automated: attempts.length > 0,
        manual_pending: manual.length,
      },
    },
  };
});

return $input.all().map((item) => ({
  json: { ok: false, rejected: true, problems: item.json.problems, lead: item.json.lead },
}));
